from dbcore import Refusal
def _figure_numbers(text):
    out = []
    for kind, readings, _w in db._retrieval_log().number_tokens(text or ""):
        if kind == "ratio":
            out += [{r[0] for r in readings}, {r[1] for r in readings}]
        else:
            out.append(set(readings))
    return out
def _refuse_unless_reformat(row, field, value):
    ctx = f"amend-extraction --field {field}: extraction {row['extraction_id']}"
    if field == "setting":
        if (row["setting"] or "").strip():
            raise Refusal(f"{ctx} already states setting")
        return
    if field == "claimed_value":
        if row["claim_type"] not in dbcore.QUANTITY_CLAIM_TYPES:
            raise Refusal(f"{ctx}: not a quantity")
        old, new = _figure_numbers(row["claimed_value"]), _figure_numbers(value)
        if len(old) != len(new) or not all(len(n) == 1 and n <= o for n, o in zip(new, old)):
            raise Refusal(f"{ctx}: not the same numbers")
        db._require_stated_numbers(row["claim_text"] or "", value, row["claim_type"], row["value_as_written"], "--claimed-value", "amend-extraction")
        figure, unit = value, row["claimed_unit"]
    else:
        if (why := dbcore.unit_refusal(value)):
            raise Refusal(f"{ctx}: {why}")
        if not db._as_whole_words(value, row["claimed_unit"]):
            raise Refusal(f"{ctx}: not in old cell")
        figure, unit = row["claimed_value"], value
    if (why := dbcore.figure_refusal(figure, unit, row["comparator"], row["claim_type"])):
